;s:38:\"//websitedemos.net/digital-designer-04\";s:20:\"astra-site-parent-id\";i:3155;s:15:\"astra-sites-tag\";a:12:{i:597;s:3:\"art\";i:3008;s:6:\"design\";i:670;s:8:\"designer\";i:2720;s:7:\"digital\";i:3158;s:10:\"digitalart\";i:3157;s:13:\"digitaldesign\";i:3160;s:20:\"digitalillustrations\";i:669;s:10:\"freelancer\";i:3156;s:16:\"graphic-designer\";i:3159;s:13:\"illustrations\";i:444;s:9:\"portfolio\";i:3161;s:9:\"webdesign\";}s:16:\"astra-sites-type\";s:11:\"agency-mini\";s:19:\"astra-site-category\";a:1:{i:27;s:8:\"business\";}s:29:\"astra-sites-template-category\";a:5:{i:2777;s:8:\"business\";i:2810;s:9:\"freelance\";i:2770;s:8:\"personal\";i:2768;s:9:\"portfolio\";i:2817;s:10:\"technology\";}s:23:\"astra-site-page-builder\";s:9:\"elementor\";s:10:\"categories\";a:3:{i:3427;s:7:\"default\";i:2488;s:9:\"portfolio\";i:3429;s:7:\"premium\";}s:16:\"required-plugins\";a:4:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:23:\"header-footer-elementor\";s:4:\"init\";s:51:\"header-footer-elementor/header-footer-elementor.php\";s:4:\"name\";s:33:\"Elementor Header & Footer Builder\";}i:2;a:3:{s:4:\"slug\";s:18:\"ultimate-elementor\";s:4:\"init\";s:41:\"ultimate-elementor/ultimate-elementor.php\";s:4:\"name\";s:29:\"Ultimate Addons for Elementor\";}i:3;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1252:\"<!-- wp:paragraph -->\n<p>The Freelance Digital Designer template is an energetic portfolio design that does a great job of hooking you in so you want to explore more. That’s a great feature of a page designed to attract new clients.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The design is modern, flat and alternates between dark and light with an orange contrast color. You can change all this if you like, but the default design has everything you need including a portfolio, contact page, biography and the opportunity to fully personalize.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Freelance Digital Designer template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Energetic design that’s instantly engaging</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>All the essential ingredients for a portfolio website</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Attractive pages and lots of imagery</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Useful supplementary pages including biography and portfolio</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:81:\"Freelance Digital Designer offers the perfect opportunity to attract new clients.\";s:5:\"pages\";a:4:{s:8:\"id-73479\";a:12:{s:5:\"title\";s:8:\"About me\";s:18:\"featured-image-url\";s:81:\"https://websitedemos.net/wp-content/uploads/2023/04/digital-designer-04-about.jpg\";s:19:\"thumbnail-image-url\";s:90:\"https://websitedemos.net/wp-content/uploads/2023/04/digital-designer-04-about-600x1966.jpg\";s:18:\"astra-page-api-url\";s:67:\"https://websitedemos.net/digital-designer-04/wp-json/wp/v2/pages/22\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:48:\"//websitedemos.net/digital-designer-04/about-me/\";s:15:\"astra-sites-tag\";a:1:{i:352;s:5:\"about\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:1:{i:60;s:8:\"business\";}s:16:\"required-plugins\";a:3:{i:0;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}i:1;a:3:{s:4:\"slug\";s:23:\"header-footer-elementor\";s:4:\"init\";s:51:\"header-footer-elementor/header-foote