:\"woocommerce\";s:4:\"init\";s:27:\"woocommerce/woocommerce.php\";s:4:\"name\";s:11:\"WooCommerce\";}i:3;a:3:{s:4:\"slug\";s:12:\"wpforms-lite\";s:4:\"init\";s:24:\"wpforms-lite/wpforms.php\";s:4:\"name\";s:12:\"WPForms Lite\";}i:4;a:3:{s:4:\"slug\";s:11:\"astra-addon\";s:4:\"init\";s:27:\"astra-addon/astra-addon.php\";s:4:\"name\";s:9:\"Astra Pro\";}i:5;a:3:{s:4:\"slug\";s:22:\"variation-swatches-woo\";s:4:\"init\";s:49:\"variation-swatches-woo/variation-swatches-woo.php\";s:4:\"name\";s:34:\"Variation Swatches for WooCommerce\";}}s:11:\"post-status\";s:7:\"publish\";s:12:\"post-content\";s:1271:\"<!-- wp:paragraph -->\n<p>Want to sell baby products online? Build an online store using our lightweight Baby Store template. The well-designed template is easy to set up and helps you start selling quickly thanks to full integration with WooCommerce.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The template is tailor-made for an online baby store, from subtle colors to having the right images in place. Showcase your latest products, best sellers, deals and offers, and customer reviews, among other things, on the homepage.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2>Key features of the Baby Store template</h2>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elegantly designed website template perfect for an online baby store</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Use the global palette to customize your store’s colors easily</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Display products based on categories, best sellers, latest arrivals, and more</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Showcase client reviews and testimonials</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Full compatibility with leading page builders</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";s:12:\"post-excerpt\";s:87:\"Elegantly designed online store website template for selling all kinds of baby products\";s:5:\"pages\";a:4:{s:8:\"id-49346\";a:12:{s:5:\"title\";s:8:\"About Us\";s:18:\"featured-image-url\";s:76:\"https://websitedemos.net/wp-content/uploads/2020/12/baby-stores-04-about.jpg\";s:19:\"thumbnail-image-url\";s:85:\"https://websitedemos.net/wp-content/uploads/2020/12/baby-stores-04-about-600x1710.jpg\";s:18:\"astra-page-api-url\";s:62:\"https://websitedemos.net/baby-store-04/wp-json/wp/v2/pages/406\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:42:\"//websitedemos.net/baby-store-04/about-us/\";s:15:\"astra-sites-tag\";a:1:{i:352;s:5:\"about\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:60;s:8:\"business\";i:64;s:9:\"ecommerce\";}s:16:\"required-plugins\";a:2:{i:0;a:3:{s:4:\"slug\";s:11:\"astra-addon\";s:4:\"init\";s:27:\"astra-addon/astra-addon.php\";s:4:\"name\";s:9:\"Astra Pro\";}i:1;a:3:{s:4:\"slug\";s:9:\"elementor\";s:4:\"init\";s:23:\"elementor/elementor.php\";s:4:\"name\";s:9:\"Elementor\";}}}s:8:\"id-49347\";a:12:{s:5:\"title\";s:10:\"Contact Us\";s:18:\"featured-image-url\";s:78:\"https://websitedemos.net/wp-content/uploads/2020/12/baby-stores-04-contact.jpg\";s:19:\"thumbnail-image-url\";s:87:\"https://websitedemos.net/wp-content/uploads/2020/12/baby-stores-04-contact-600x1158.jpg\";s:18:\"astra-page-api-url\";s:62:\"https://websitedemos.net/baby-store-04/wp-json/wp/v2/pages/564\";s:12:\"dynamic-page\";s:2:\"no\";s:14:\"astra-page-url\";s:44:\"//websitedemos.net/baby-store-04/contact-us/\";s:15:\"astra-sites-tag\";a:1:{i:415;s:7:\"contact\";}s:15:\"site-pages-type\";s:11:\"agency-mini\";s:23:\"site-pages-page-builder\";s:9:\"elementor\";s:19:\"site-pages-category\";a:0:{}s:26:\"site-pages-parent-category\";a:2:{i:60;s:8:\"business\";i:64;s:9:\"ecommerce\";}s:16:\"required-plugins\";a:3:{i:0;a:3:{s:4:\"slug\";s:11:\"astra-addon\";s:4:\"init\";s:27:\"astra-addon/astra-addon.php\